/* Global saved-edit preflight is single-pass and local replay stays exact.
 * All terrain is generated by MineWorld; no proprietary art is used. */
'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const ctx=vm.createContext({window:{}});
for(const name of ['world-depth.js','overworld-ores.js','world-chunks.js'])
 vm.runInContext(fs.readFileSync(path.join(__dirname,'..',name),'utf8'),ctx,{filename:name});
const biomes=ctx.window.MineWorldBiomes,depth=ctx.window.MineWorldWorldDepth;
const signed={minX:-32,minZ:-32,width:64,depth:64,H:384,minY:-64,SEA:63};
const codec=depth.create({...signed,maxY:319});
const local=(x,y,z,cx=-2,cz=-2)=>((x-cx*16)*16+(z-cz*16))*384+(y+64);
class CountingMap extends Map {
 constructor(entries){super(entries);this.passes=0;}
 [Symbol.iterator](){this.passes++;return super[Symbol.iterator]();}
}
test('deep terrain validates and replays global saved edits in a single iteration',()=>{
 const entries=[
  [codec.index(-31,-64,-31),11],[codec.index(-17,319,-17),7],
  [codec.index(-30,63,-30),0],[codec.index(0,-64,0),22]
 ];
 const edits=new CountingMap(entries);
 const data=biomes.generateChunk({cx:-2,cz:-2,...signed,edits});
 assert.equal(edits.passes,1,'one preflight pass, no global replay scan');
 assert.equal(data[local(-31,-64,-31)],11);
 assert.equal(data[local(-17,319,-17)],7);
 assert.equal(data[local(-30,63,-30)],0);
 assert.equal(edits.size,4,'source map remains untouched');
});
test('foreign signed-chunk edits do not leak across negative and zero seams',()=>{
 const edits=new CountingMap([
  [codec.index(-1,-64,-1),25],[codec.index(0,-64,0),11],
  [codec.index(-16,-64,-16),7],[codec.index(-17,-64,-17),21]
 ]);
 const west=biomes.generateChunk({cx:-1,cz:-1,...signed,edits});
 assert.equal(west[local(-1,-64,-1,-1,-1)],25);
 assert.equal(west[local(-16,-64,-16,-1,-1)],7);
 const east=biomes.generateChunk({cx:0,cz:0,...signed,edits});
 assert.equal(east[local(0,-64,0,0,0)],11);
 assert.equal(edits.passes,2,'one iteration per generated chunk');
});
test('legacy saved air and placed blocks still override generated terrain',()=>{
 const legacy=depth.create({width:10000,depth:10000,minY:0,maxY:47});
 const edits=new CountingMap([
  [legacy.index(1,14,1),0],[legacy.index(15,47,15),119],
  [legacy.index(16,0,16),21]
 ]);
 const data=biomes.generateChunk({cx:0,cz:0,edits});
 assert.equal(data[(1*16+1)*48+14],0);
 assert.equal(data[(15*16+15)*48+47],119);
 assert.equal(edits.passes,1);
});
test('late invalid global edit aborts before ore generation without mutating save',()=>{
 const ores=ctx.window.MineWorldOres,original=ores.generate;
 let called=0;ores.generate=(...args)=>{called++;return original(...args);};
 const edits=new CountingMap([
  [codec.index(-31,-64,-31),7],[codec.index(0,63,0),0],[codec.volume,21]
 ]);
 try{
  assert.throws(()=>biomes.generateChunk({cx:-2,cz:-2,...signed,edits}),/Invalid saved chunk edit/);
  assert.equal(called,0);
  assert.equal(edits.passes,1);
  assert.equal(edits.size,3);
 }finally{ores.generate=original;}
});
